        emon.Testport.AssertEq(emon.Port.BufAt(@out, emon.Port.BufLen(@out) - 7), 69, "E");
        emon.Testport.AssertEq(emon.Port.BufAt(@out, emon.Port.BufLen(@out) - 6), 78, "N");
        emon.Testport.AssertEq(emon.Port.BufAt(@out, emon.Port.BufLen(@out) - 5), 68, "D");
    }
