        Pngprobe.PpBuild(2, ws, @out, z, raw, row, st, pal);
        emon.Testport.AssertEq(PtRead(emon.Port.BufBlob(@out), info, idat), 0, "well formed before");
        v = emon.Port.BufAt(@out, 20);
