        emon.Testport.AssertEq(PtRead(emon.Port.BufBlob(@out), info, idat), 2, "IDAT CRC fails");
        emon.Port.BufSet(@out, 60, v);
        emon.Testport.AssertEq(PtRead(emon.Port.BufBlob(@out), info, idat), 0, "well formed again");
