    [Xunit.Fact]
    public static void TestTheFilterIsTheOneWithTheSmallestSumTiesToTheLower() {
        // A gray 64x8 image of identical rows, each a ramp of step 3. Row 0: `none`
        // sums 3*(0+..+63), `sub` is 3 a byte, `paeth` of a row with nothing above
        // is `sub` again, so `sub` wins the tie on being lower. Rows 1..7: `up` is
        // all zeros, and so is `paeth`; `up` wins. So filters: 1 once, 2 seven times.
        emon.Port.Cells ws = emon.Port.NewCells();
        emon.Port.Buf @out = emon.Port.NewBuf();
        emon.Port.Buf z = emon.Port.NewBuf();
        emon.Port.Cells row = emon.Port.NewCells();
        emon.Port.Cells pal = emon.Port.NewCells();
        emon.Port.Cells info = emon.Port.NewCells();
        emon.Port.Cells dec = emon.Port.NewCells();
        emon.Port.Cells ist = emon.Port.NewCells();
        emon.Port.Buf idat = emon.Port.NewBuf();
        int y = 0;
        int i = 0;
        while (i < 16) {
            emon.Port.CellsPush(info, 0);
            i += 1;
        }
        Png.PngBegin(ws, @out, z, 64, 8, 0, 8, 0, pal, 0, 0);
        while (y < 8) {
            emon.Port.CellsDrop(row, 0);
            i = 0;
            while (i < 64) {
                emon.Port.CellsPush(row, i * 3);
                i += 1;
            }
            Png.PngRow(ws, @out, z, row, 0);
            y += 1;
        }
        Png.PngEnd(ws, @out, z);
        emon.Testport.AssertEq(PtRead(emon.Port.BufBlob(@out), info, idat), 0, "well formed");
        emon.Testport.AssertEq(PtDecode(idat, info, dec, ist), 0, "inflates");
        emon.Testport.AssertEq(emon.Port.CellsAt(info, IF0 + 0), 0, "no row with none");
        emon.Testport.AssertEq(emon.Port.CellsAt(info, IF0 + 1), 1, "one row with sub");
        emon.Testport.AssertEq(emon.Port.CellsAt(info, IF0 + 2), 7, "seven rows with up");
        emon.Testport.AssertEq(emon.Port.CellsAt(info, IF0 + 3), 0, "none with average");
        emon.Testport.AssertEq(emon.Port.CellsAt(info, IF0 + 4), 0, "none with paeth");
    }
