        emon.Port.BufTruncate(@out, 0);
        emon.Port.BufTruncate(raw, 0);
        Pngprobe.PpBuild(4, ws, @out, z, raw, row, st, pal);
        emon.Testport.AssertEq(PtRead(emon.Port.BufBlob(@out), info, idat), 0, "1-bit image, well formed");
        emon.Testport.AssertEq(PtDecode(idat, info, dec, ist), 0, "inflates");
        emon.Testport.AssertEq(emon.Port.CellsAt(info, IF0 + 0), 17, "all 17 rows filter none (1-bit)");
    }
    [Xunit.Fact]
    public static void TestAWriterReusedForASecondImageGivesTheSameFile() {
        // The workspace is cleared by png-begin: a second image through the same
        // buffers is byte for byte the first built fresh.
        emon.Port.Cells ws = emon.Port.NewCells();
        emon.Port.Buf o1 = emon.Port.NewBuf();
        emon.Port.Buf o2 = emon.Port.NewBuf();
        emon.Port.Buf z = emon.Port.NewBuf();
        emon.Port.Buf raw = emon.Port.NewBuf();
        emon.Port.Cells row = emon.Port.NewCells();
        emon.Port.Cells st = emon.Port.NewCells();
        emon.Port.Cells pal = emon.Port.NewCells();
        emon.Port.Cells ws2 = emon.Port.NewCells();
        emon.Port.Buf z2 = emon.Port.NewBuf();
        emon.Port.Buf raw2 = emon.Port.NewBuf();
        emon.Port.Buf o3 = emon.Port.NewBuf();
        int i = 0;
        int same = 1;
        Pngprobe.PpBuild(3, ws, o1, z, raw, row, st, pal);
        Pngprobe.PpBuild(1, ws, o2, z, raw, row, st, pal);
        emon.Port.BufTruncate(raw, 0);
        emon.Port.BufTruncate(o1, 0);
        Pngprobe.PpBuild(1, ws, o1, z, raw, row, st, pal);
        Pngprobe.PpBuild(1, ws2, o3, z2, raw2, row, st, pal);
        emon.Testport.AssertEq(emon.Port.BufLen(o2), emon.Port.BufLen(o1), "same length after a different image");
        emon.Testport.AssertEq(emon.Port.BufLen(o3), emon.Port.BufLen(o1), "and as a fresh one");
        while (i < emon.Port.BufLen(o1)) {
            if (emon.Port.BufAt(o1, i) != emon.Port.BufAt(o2, i)) {
                same = 0;
            }
            if (emon.Port.BufAt(o1, i) != emon.Port.BufAt(o3, i)) {
                same = 0;
            }
            i += 1;
        }
        emon.Testport.AssertEq(same, 1, "same bytes");
    }
